#!/usr/bin/env node
// ---------------------------------------------------------------------------
// THE COMMITTED BUNDLES MUST MATCH THE MIGRATIONS THEY ARE GENERATED FROM.
//
// `supabase/apply/*.sql`, `Spare_1.sql` and `HandStock_X.sql` are GENERATED by
// scripts/build-apply-bundles.mjs. They are also the files the user is sent a
// LINK to and asked to run against the live Supabase project — so a bundle that
// has drifted from its migrations is not a stale build artefact, it is wrong
// SQL handed to somebody as the thing to run.
//
// It happened (2026-09-14). `0186_feedback_key.sql` was corrected to drop a
// PARTIAL unique index — partial indexes are not inferable upsert targets, which
// is what check:upserts exists to refuse — and the migration was committed
// without re-running the generator. The committed `data_integrity.sql` went on
// carrying `create unique index ... where ucn_key <> ''`, and that is the file
// whose raw link was given out. Nothing caught it: check:replay and
// check:status both build their database from the bundles, so a bundle and an
// all.sql that are stale in the SAME way agree with each other perfectly.
//
// This check asks the only question those cannot: does regenerating change
// anything? It writes nothing — it builds into a temporary directory and
// compares.
//
//   node scripts/check-generated.mjs
// ---------------------------------------------------------------------------
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, readdirSync, existsSync, rmSync, cpSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const OUT = ['supabase/apply', '.'];

// Build into a copy of the repo's generated files, so the working tree is never
// touched by a check.
const tmp = mkdtempSync(join(tmpdir(), 'genchk-'));
try {
  cpSync('supabase', join(tmp, 'supabase'), { recursive: true });
  cpSync('scripts', join(tmp, 'scripts'), { recursive: true });
  execFileSync('node', ['scripts/build-apply-bundles.mjs'], { cwd: tmp, stdio: 'pipe' });

  const drifted = [];
  const generated = [];
  for (const dir of OUT) {
    const here = dir === '.' ? '.' : dir;
    for (const f of readdirSync(here === '.' ? '.' : here)) {
      if (!f.endsWith('.sql')) continue;
      const rel = here === '.' ? f : `${here}/${f}`;
      const built = join(tmp, rel);
      if (!existsSync(built)) continue;          // hand-maintained (_status.sql, _state_check.sql)
      generated.push(rel);
      if (readFileSync(rel, 'utf8') !== readFileSync(built, 'utf8')) drifted.push(rel);
    }
  }

  if (drifted.length) {
    console.error('\nA GENERATED bundle does not match its migrations. These are the files');
    console.error('people are given a link to and asked to RUN, so a stale one is wrong SQL');
    console.error('handed over as the thing to apply — and no other check can see it, because');
    console.error('check:replay and check:status both build from the bundles themselves.\n');
    drifted.forEach((f) => console.error(`  ✗ ${f}`));
    console.error('\nRun: node scripts/build-apply-bundles.mjs   — and commit the result.\n');
    process.exit(1);
  }

  console.log(`\nevery generated bundle matches its migrations (${generated.length} checked)\n`);
} finally {
  rmSync(tmp, { recursive: true, force: true });
}
